# Generated by the AMP Nimbus instance template.
param(
    [Parameter(Mandatory = $true)][string]$Root,
    [Parameter(Mandatory = $true)][string]$Components
)

$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12

$repo = 'StratumServer/Nimbus'
$comps = @($Components -split '[,\s]+' | Where-Object { $_ -ne '' })
$headers = @{ 'User-Agent' = 'AMP-Nimbus-Template'; 'Accept' = 'application/vnd.github+json' }
if ($env:GITHUB_TOKEN) { $headers['Authorization'] = "Bearer $($env:GITHUB_TOKEN)" }

$tag = if ($env:NIMBUS_TAG) { $env:NIMBUS_TAG.Trim() } else { '' }
if ($tag -eq '') {
    $channel = if ($env:NIMBUS_CHANNEL) { $env:NIMBUS_CHANNEL } else { 'stable' }
    Write-Host "[AMP] resolving Nimbus release (channel=$channel)"
    $releases = Invoke-RestMethod -Headers $headers -Uri "https://api.github.com/repos/$repo/releases?per_page=100"
    $candidates = @($releases | Where-Object { -not $_.draft })
    if ($channel -ne 'prerelease') { $candidates = @($candidates | Where-Object { -not $_.prerelease }) }
    if ($candidates.Count -eq 0) { throw "No Nimbus release matched channel=$channel" }
    $tag = $candidates[0].tag_name
}
if (-not $tag.StartsWith('v')) { $tag = "v$tag" }

$marker = Join-Path $Root '.amp-nimbus-release'
if ((Test-Path $marker) -and ((Get-Content $marker -Raw).Trim() -eq $tag)) {
    $missing = @($comps | Where-Object { -not (Test-Path (Join-Path $Root $_)) })
    if ($missing.Count -eq 0) {
        Write-Host "[AMP] already on Nimbus $tag; nothing to download"
        exit 0
    }
}

$extract = Join-Path $Root '.nimbus-extract'
if (Test-Path $extract) { Remove-Item $extract -Recurse -Force }
New-Item -ItemType Directory -Force -Path $extract | Out-Null

$zip = Join-Path $Root 'nimbus-release.zip'
$url = "https://github.com/$repo/releases/download/$tag/Nimbus-$tag.zip"
Write-Host "[AMP] downloading $url"
Invoke-WebRequest -UseBasicParsing -Headers $headers -Uri $url -OutFile $zip
Expand-Archive -Path $zip -DestinationPath $extract -Force
Remove-Item $zip -Force

$src = Join-Path $extract 'release_full'
if (-not (Test-Path $src)) { $src = $extract }

$programPatterns = @('*.dll', '*.pdb', '*.deps.json', '*.runtimeconfig.json', 'web.config', '*.staticwebassets.endpoints.json')
foreach ($comp in $comps) {
    $from = Join-Path $src $comp
    if (-not (Test-Path $from)) { throw "Component $comp is not present in this release" }
    $to = Join-Path $Root $comp
    New-Item -ItemType Directory -Force -Path $to | Out-Null
    # Replace program files only; nimbus.proxy.toml, state files and plugins stay put.
    foreach ($pattern in $programPatterns) {
        Get-ChildItem -LiteralPath $to -Filter $pattern -File -ErrorAction SilentlyContinue | Remove-Item -Force
    }
    Copy-Item -Path (Join-Path $from '*') -Destination $to -Recurse -Force
}

$license = Join-Path $src 'LICENSE'
if (Test-Path $license) { Copy-Item -Path $license -Destination (Join-Path $Root 'LICENSE') -Force }

Remove-Item $extract -Recurse -Force
Set-Content -Path $marker -Value $tag -NoNewline
Write-Host "[AMP] installed Nimbus $tag ($Components) into $Root"

# Renders nimbus.registry.toml from environment variables set by AMP.
# Generated by the AMP Nimbus instance template; edits here are overwritten on the next update.
param([Parameter(Mandatory = $true)][string]$Out)
$ErrorActionPreference = 'Stop'

function D([string]$v, [string]$d) { if ([string]::IsNullOrWhiteSpace($v)) { return $d } return $v }
function Esc([string]$s) { if ($null -eq $s) { return '' } return $s.Replace('\', '\\').Replace('"', '\"') }
function B([string]$s) { if ($null -eq $s) { return 'false' } if (@('true', '1', 'yes', 'on') -contains $s.Trim().ToLowerInvariant()) { return 'true' } return 'false' }
function I([string]$s, [int]$d) { $n = 0; if ([int]::TryParse(($s -replace '\s', ''), [ref]$n)) { return "$n" } return "$d" }
function L([string]$s) {
    $parts = @()
    foreach ($x in ($s -split ',')) { $t = $x.Trim(); if ($t -ne '') { $parts += ('"' + (Esc $t) + '"') } }
    return '[' + ($parts -join ', ') + ']'
}
function Pair([string]$x) {
    $i = $x.IndexOf('=')
    if ($i -lt 1) { return $null }
    return @{ Key = $x.Substring(0, $i).Trim(); Value = $x.Substring($i + 1).Trim() }
}
function SrvLines($list, [string]$s) {
    foreach ($x in ($s -split ',')) {
        $t = $x.Trim(); if ($t -eq '') { continue }
        $p = Pair $t
        if ($null -eq $p -or $p.Key -eq '' -or $p.Value -eq '') { Write-Output "skipping malformed servers entry '$t' (expected id=host:port)"; continue }
        $list.Add('"' + (Esc $p.Key) + '" = "' + (Esc $p.Value) + '"')
    }
}
function FhLines($list, [string]$s) {
    foreach ($x in ($s -split ',')) {
        $t = $x.Trim(); if ($t -eq '') { continue }
        $p = Pair $t
        if ($null -eq $p -or $p.Key -eq '') { Write-Output "skipping malformed forced_hosts entry '$t' (expected hostname=id1|id2)"; continue }
        $list.Add('"' + (Esc $p.Key) + '" = ' + (L ($p.Value -replace '\|', ',')))
    }
}
function Mods([string]$s) {
    $parts = @()
    foreach ($x in ($s -split ',')) {
        $t = $x.Trim(); if ($t -eq '') { continue }
        $p = Pair $t
        if ($null -eq $p) { $parts += ('{ id = "' + (Esc $t) + '", version = "" }') }
        else { $parts += ('{ id = "' + (Esc $p.Key) + '", version = "' + (Esc $p.Value) + '" }') }
    }
    return '[' + ($parts -join ', ') + ']'
}
function KeepSecret([string]$key, [string]$val, [string]$file) {
    if (-not [string]::IsNullOrWhiteSpace($val)) { return $val }
    if (Test-Path -LiteralPath $file) {
        $pattern = '^\s*' + [regex]::Escape($key) + '\s*=\s*"(.*)"'
        $m = Select-String -LiteralPath $file -Pattern $pattern | Select-Object -First 1
        if ($m) {
            $cur = $m.Matches[0].Groups[1].Value
            if ($cur -ne '' -and $cur -ne 'change-me-and-keep-secret') { return $cur }
        }
    }
    Write-Host ("[AMP] no $key set, generating a random one; read it out of " + (Split-Path -Leaf $file) + " and paste it into every backend")
    $bytes = New-Object byte[] 32
    $rng = [System.Security.Cryptography.RandomNumberGenerator]::Create()
    $rng.GetBytes($bytes)
    return (($bytes | ForEach-Object { $_.ToString('x2') }) -join '')
}

if ((B (D $env:NR_WRITE 'true')) -ne 'true') {
    Write-Output ("AMP management of " + (Split-Path -Leaf $Out) + " is disabled, leaving the existing file alone")
    exit 0
}

$dir = Split-Path -Parent $Out
if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
$L = New-Object System.Collections.Generic.List[string]
$L.Add('bind_url = "' + (Esc (D $env:NR_BIND 'http://0.0.0.0:8765')) + '"')
$L.Add('shared_secret = "' + (Esc (KeepSecret 'shared_secret' $env:NR_SECRET $Out)) + '"')
$L.Add('accepted_secrets = ' + (L (D $env:NR_ACCEPTED '')))
$L.Add('backend_stale_seconds = ' + (I (D $env:NR_STALE '20') 20))
$L.Add('backend_drop_seconds = ' + (I (D $env:NR_DROP '120') 120))
$L.Add('nonce_window_seconds = ' + (I (D $env:NR_NONCE '90') 90))
$L.Add('max_reservation_ttl_seconds = ' + (I (D $env:NR_MAXRESTTL '300') 300))
$L.Add('log_heartbeats = ' + (B (D $env:NR_LOGHB 'false')))
$L.Add('state_dir = "' + (Esc (D $env:NR_STATEDIR '.')) + '"')
$L.Add('')
$L.Add('[api_tokens]')
$L.Add('enabled = ' + (B (D $env:NR_APITOK 'false')))
$L.Add('rate_limit_per_minute = ' + (I (D $env:NR_APIRATE '60') 60))
$L.Add('trust_forwarded_proto = ' + (B (D $env:NR_APIFWD 'false')))
$L.Add('')
$L.Add('[identity]')
$L.Add('advertise_on_master_server = ' + (B (D $env:NR_I_ADVERTISE 'false')))
$L.Add('master_server_url = "' + (Esc (D $env:NR_I_MSURL 'http://masterserver.vintagestory.at/api/v1/servers/')) + '"')
$L.Add('public_host = "' + (Esc (D $env:NR_I_HOST '127.0.0.1')) + '"')
$L.Add('public_port = ' + (I (D $env:NR_I_PORT '42420') 42420))
$L.Add('server_name = "' + (Esc (D $env:NR_I_NAME 'Nimbus Network')) + '"')
$L.Add('server_description = "' + (Esc (D $env:NR_I_DESC '')) + '"')
$L.Add('server_url = "' + (Esc (D $env:NR_I_URL '')) + '"')
$L.Add('server_icon = "' + (Esc (D $env:NR_I_ICON '')) + '"')
$L.Add('vh_identifier = "' + (Esc (D $env:NR_I_VHID '')) + '"')
$L.Add('game_version = "' + (Esc (D $env:NR_I_GAMEVER '1.22.2')) + '"')
$L.Add('max_players_override = ' + (I (D $env:NR_I_MAXPLAYERS '0') 0))
$L.Add('mod_source = "' + (Esc (D $env:NR_I_MODSOURCE 'aggregate')) + '"')
$L.Add('explicit_mods = ' + (Mods (D $env:NR_I_MODS '')))
$L.Add('whitelisted = ' + (B (D $env:NR_I_WHITELISTED 'false')))
$L.Add('has_password = ' + (B (D $env:NR_I_HASPASSWORD 'false')))
$L.Add('heartbeat_interval_seconds = ' + (I (D $env:NR_I_HB '120') 120))
$L.Add('')
$L.Add('[identity.playstyle]')
$L.Add('id = "' + (Esc (D $env:NR_I_PSID 'surviveandbuild')) + '"')
$L.Add('lang_code = "' + (Esc (D $env:NR_I_PSLANG 'preset-surviveandbuild')) + '"')
$tmp = "$Out.amptmp"
Set-Content -LiteralPath $tmp -Value $L -Encoding UTF8
Move-Item -LiteralPath $tmp -Destination $Out -Force
Write-Output "wrote $Out"
